$ErrorActionPreference = 'Stop'
if ($env:RUNNER_NAME -ne $env:EXPECTED_RUNNER) { throw 'Runner route mismatch.' }
$probeArgs=@('--public-config','apps/clued-cloud/app/supabase-public-config.ts')
if ($env:QUALIFICATION_EVENT -eq 'pull_request') { $probeArgs+=@('--candidate','--hook','scripts/runner/clued-runner-job-started.mjs') }
$report = & node scripts/runner/qualify-work-handover.mjs @probeArgs
if ($LASTEXITCODE -ne 0) { throw 'Hook qualification failed.' }
Set-Content -LiteralPath handover-hook-qualification.json -Value $report -Encoding UTF8
Write-Output $report

